export const weeks=[
 {n:1,title:'Find your room.',outcome:'An event shortlist and a sourced requirements map.',tasks:['Choose one event and track.','Check eligibility, edition, deadline and AI policy on the official site.','Map required headings and criteria to your project.'],route:'events',action:'Explore event references'},
 {n:2,title:'Build something you can defend.',outcome:'A clear story with evidence gaps visible.',tasks:['Describe the user, problem and working solution.','Attach real sources; label goals and assumptions.','Ask a peer which claim is hardest to believe.'],route:'projects',action:'Open your projects'},
 {n:3,title:'Make the pitch travel.',outcome:'A draft deck and a rehearsable demo.',tasks:['Use the organizer’s template where required.','Assign speakers and prepare a demo fallback.','Exchange a specific, constructive peer review.'],route:'projects',action:'Prepare your pitch'},
 {n:4,title:'Practise. Check. Submit.',outcome:'Reviewed files and a recorded submission reference.',tasks:['Run a timed rehearsal and questions.','Open the exports and inspect every slide.','Submit on the official portal and save its receipt.'],route:'practice',action:'Open rehearsal tools'}
];
export function calendarPlan(date){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(date))throw Error('Choose a valid start date.');
 const start=new Date(date+'T00:00:00Z');if(!Number.isFinite(+start)||start.toISOString().slice(0,10)!==date||start.getUTCFullYear()<2026||start.getUTCFullYear()>2100)throw Error('Choose a valid start date between 2026 and 2100.');
 const stamp=d=>d.toISOString().replace(/[-:]/g,'').replace('.000','');
 return ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//DayZero//Personal preparation plan//EN','CALSCALE:GREGORIAN',...weeks.flatMap((w,i)=>{const at=new Date(+start+i*7*86400000+4.5*3600000);return ['BEGIN:VEVENT',`UID:dayzero-personal-${date}-${w.n}@dayzero.local`,'DTSTAMP:20261106T000000Z',`DTSTART:${stamp(at)}`,`DTEND:${stamp(new Date(+at+3600000))}`,`SUMMARY:Personal prep week ${w.n}: ${w.title}`,`DESCRIPTION:${w.outcome} Personal work block only. No hosted session or enrollment is booked.`,'END:VEVENT'];}),'END:VCALENDAR',''].join('\r\n');
}
const path=()=>`<div class="cohort-path">${weeks.map(w=>`<article><span class="eyebrow">WEEK 0${w.n}</span><h3>${w.title}</h3><p>${w.outcome}</p><ul>${w.tasks.map(t=>`<li>${t}</li>`).join('')}</ul><button class="btn text" data-route="${w.route}">${w.action} ↗</button></article>`).join('')}</div>`;
export function communityHome(){return `<section class="community-hero"><div><span class="eyebrow">THE COMPETITION PREPARATION COMMUNITY / PLANNED PILOT</span><h1>Find your room.<br><em>Build your way in.</em></h1><p>A focused four-week journey from choosing an opportunity to presenting a story you can defend. The free workspace is ready today. The hosted community pilot is being prepared.</p><div class="toolbar"><button class="btn primary" data-route="plans">Explore the four-week pilot ↗</button><button class="btn" data-action="new">Start a free project</button></div><small>No subscription or payment today. Pilot enrollment is not open.</small></div><aside class="community-note"><span>YOUR NEXT FOUR WEEKS</span><strong>One event.<br>One team.<br>A clearer<br><em>next step.</em></strong><p>Sources before claims.<br>Practice before the room.</p><b aria-hidden="true">✳</b></aside></section><div class="community-strip"><span>01 Find a suitable event</span><span>02 Develop the evidence</span><span>03 Rehearse together</span><span>04 Review the submission</span></div><section class="cohort-section"><div class="section-head"><div><span class="eyebrow">A PROCESS YOU CAN START NOW</span><h2>Less guessing.<br><em>More forward motion.</em></h2></div><button class="btn" data-action="demo">Explore the fictional sample ↗</button></div>${path()}</section><section class="community-boundary"><h2>A useful community earns its place.</h2><p>The proposed pilot pairs preparation tools with scheduled sessions, peer feedback and a scoped submission review. Hosts, dates, review capacity and terms will be published before enrollment opens. There is no member directory, live chat or mentor booking in this release.</p><button class="btn" data-route="events">Start with the event library ↗</button></section>`;}
export function communityPlans(){return `<div class="page-heading"><span class="eyebrow">FOUR WEEKS / ONE FOCUSED PREPARATION JOURNEY</span><h1>Prepare with purpose.<br><em>Bring people into it.</em></h1><p>The free workspace is available now. The community pilot below is the proposed next service, with enrollment closed until delivery is arranged.</p></div><div class="cohort-offer"><article class="panel"><span class="pill">AVAILABLE NOW</span><h2>The preparation workspace</h2><strong class="cohort-price">Free</strong><p>Local projects, story editing, proof board, requirement mapping, speaking plans, rehearsal and editable exports.</p><button class="btn primary" data-action="new">Create a project ↗</button><p class="hint">Export backups to keep your work. Drafts expire after 24 hours without an edit, checked on opening.</p></article><article class="panel pilot-offer"><span class="pill amber">PLANNED PILOT / ENROLLMENT CLOSED</span><h2>The four-week cohort</h2><strong class="cohort-price">₹499 <small>proposed / participant</small></strong><ul><li>A small event shortlist checked against official sources.</li><li>One scheduled preparation session each week.</li><li>Structured peer feedback and optional team introductions.</li><li>One submission review per team, with a published scope.</li><li>Rule-change notices for the selected events.</li></ul><p>Price, taxes, dates, host, cohort capacity, review turnaround and cancellation terms must be confirmed before payment. No seat is reserved and no charge is taken here.</p></article></div>${path()}<section class="panel personal-plan"><span class="eyebrow">START WITH A PERSONAL PLAN</span><h2>Put preparation on your calendar.</h2><p>Download four one-hour personal work blocks, one week apart at 10:00 AM India time. These are your reminders, not hosted sessions or an enrollment confirmation.</p><form id="cohort-calendar"><div class="field"><label for="cohort-start">Your first preparation day</label><input id="cohort-start" name="start" type="date" required min="2026-01-01" max="2100-12-31"></div><button class="btn" type="submit">Download personal calendar ↓</button><p id="cohort-calendar-status" role="status"></p></form></section><section class="community-boundary"><h2>Before a paid seat opens.</h2><p>We will publish the host, delivery schedule, who the cohort suits, exact review limits, total payable price, cancellation terms and contact details. Live community operations and payment are not active yet. Competition eligibility and winning are never guaranteed.</p></section>`;}
if(typeof document!=='undefined')document.addEventListener('submit',e=>{if(e.target.getAttribute('id')!=='cohort-calendar')return;e.preventDefault();const status=document.querySelector('#cohort-calendar-status');try{const date=new FormData(e.target).get('start'),text=calendarPlan(date),url=URL.createObjectURL(new Blob([text],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='dayzero-personal-preparation.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);status.textContent='Personal calendar downloaded. No enrollment or hosted meeting has been booked.';}catch(err){status.textContent=err.message;}});
